import type { FlightInput, PhysicalState, Vector3 } from '../../domains/flight/models.ts';
import type { RunWorld } from '../../domains/good-lift/models.ts';
// Browser/Node capture harness for the canonical proportional controls. Expected values are
// frozen by Chromium in fixtures/good-lift-brakes-chromium.json, never generated by a test run.
import { createFlight, stepFlight, WING } from '../../domains/flight/flight.ts';
import { createSwingWatch } from '../../domains/coaching/swing-watch.ts';
import { createStyle } from '../../domains/good-lift/meet-style.ts';
import { createComboStyle } from '../../domains/good-lift/meet-combo.ts';
import { GLIDERS, planFor } from '../../domains/good-lift/gliders.ts';
import { createFlightCoach } from '../../domains/coaching/flight-coach.ts';
import { createCloudbaseRun } from '../../domains/good-lift/cloudbase-state.ts';
import { createMeet } from '../../domains/good-lift/meet-state.ts';
import { createBells } from '../../domains/good-lift/bells.ts';
import { createRunWorld, finishRun, startRun, stepFrame } from '../../domains/good-lift/run-step.ts';
import { createRecorder, encodeLog, frameInput, inputFrame } from '../../domains/good-lift/recorder.ts';
import { createReferenceKeys, TST } from '../../domains/good-lift/pilots.ts';
import { createControlSummary } from '../../domains/flight/brake-controls.ts';
import { summariseRun } from '../../domains/good-lift/meet-sheet.ts';
import { SIM_VERSION } from '../../domains/good-lift/sim-version.ts';
import { DAILY_EPOCH } from '../../domains/good-lift/good-lift-address.ts';
import { seedFor } from '../../domains/good-lift/daily.ts';

export const BRAKE_CAPTURE_DAY = DAILY_EPOCH + 30;
// The runs fly the EN-A every pilot starts on, as the game does; the pure flights the classic wing.
const RUN_WING = GLIDERS[0];
const dt = 1 / 60;
const pair = (leftBrake = 0, rightBrake = leftBrake, extra: FlightInput = {}): FlightInput => ({ controlMode: 'brakes', leftBrake, rightBrake, ...extra });
const checkAt = new Set([1, 60, 300, 600, 900, 1200, 1800, 2700, 3600, 5400]);
const wingKeys = ['controlMode', 'leftBrake', 'rightBrake', 'leftBrakeTarget', 'rightBrakeTarget', 'brake', 'brakeTarget', 'deepBrake',
  'bar', 'ears', 'wingPhase', 'recoverySource', 'inflation', 'separation', 'stallExposure', 'frontExposure',
  'releaseExposure', 'backflyFor', 'recoveryFor', 'stallAge', 'stallWarning', 'frontalRisk', 'folded', 'energy'] as const;

export function brakeSnapshot(world: Pick<RunWorld, 'g' | 'watch' | 'style'>) {
  const { g, watch, style } = world;
  const wing = Object.fromEntries(wingKeys.map(key => [key, g.physical[key]])) as Pick<PhysicalState, typeof wingKeys[number]>;
  // In legacy mode side travel is display telemetry derived from bank feedback, whose inverse
  // trig can differ at the last bit between V8 builds. Direct-mode brake state remains exact.
  if (wing.controlMode !== 'brakes') for (const key of ['leftBrake', 'rightBrake', 'leftBrakeTarget', 'rightBrakeTarget'] as const) {
    wing[key] = Math.round(wing[key] * 1e12) / 1e12;
  }
  for (const key of ['stallWarning', 'frontalRisk'] as const) wing[key] = Math.round(wing[key] * 1e11) / 1e11;
  return JSON.parse(JSON.stringify({ pilot: g.pilot, canopy: g.canopy,
    wing, watch: watch.state, style: style!.state },
  // Derived display acceleration and warning ratios use the cross-engine precision of existing
  // receipts. Physical bodies, envelope state, event counts, style and scores stay exact.
  (key, value) => key === 'rollAcceleration' && typeof value === 'number' ? Math.round(value * 1e11) / 1e11 : value));
}

function patternedPair(tick: number) {
  const phase = (tick / 60) % 48;
  if (phase < 2 || phase >= 44) return pair();
  if (phase < 20) return pair([0.1, 0.2, 0.3][Math.floor((phase - 2) / 6)], 0);
  if (phase < 23) return pair();
  if (phase < 41) return pair(0, [0.1, 0.2, 0.3][Math.floor((phase - 23) / 6)]);
  if (phase < 42) return pair(0.4);
  if (phase < 43) return pair(0, 0, { ears: true });
  return pair(0, 0, { bar: true });
}

export function captureBrakeRun(kind: string) {
  const day = BRAKE_CAPTURE_DAY, seed = seedFor(day);
  const world = startRun(createRunWorld({ sky: createCloudbaseRun(), meet: createMeet(), bells: createBells(), style: createComboStyle(), wing: RUN_WING }), seed);
  const recorder = createRecorder(), keys = createReferenceKeys({ ...TST, plan: planFor(RUN_WING) }), checkpoints = [];
  let ending = null;
  while (!ending) {
    const tick = recorder.steps;
    const direct = kind === 'direct' || Math.floor(tick / 2700) % 2 === 1;
    const frame = direct ? inputFrame(patternedPair(tick)) : keys(world);
    recorder.push(frame);
    ending = stepFrame(world, frame);
    if (checkAt.has(recorder.steps)) checkpoints.push({ step: recorder.steps, snapshot: brakeSnapshot(world) });
  }
  finishRun(world, ending);
  const sheet = summariseRun(world, ending);
  const link = encodeLog({ simVersion: SIM_VERSION, glider: RUN_WING, seed, day, initials: 'REN', total: sheet.total, peak: sheet.peak }, recorder.bits, recorder.steps);
  return { kind, pureFlight: false, simVersion: SIM_VERSION, glider: RUN_WING, seed, day, steps: recorder.steps, link, sheet,
    checkpoints, snapshot: brakeSnapshot(world) };
}

export function captureBrakeRecovery(scenario: string) {
  const origin = { x: 0, y: 2000, z: 0 }, g = createFlight({ ...origin }), watch = createSwingWatch(), style = createStyle();
  const controls = {}, world = { g, watch, style, controls }, summary = createControlSummary(), coach = createFlightCoach(), recorder = createRecorder();
  const checkpoints = [], phases = [];
  let input = pair(), stalledAt = null, backflyAt = null, handedAt = null, recoveredAt = null;
  let pending = null, lastAction = '', lastPhase = '';
  for (let tick = 0; tick < 70 * 60; tick++) {
    const time = tick * dt;
    if (handedAt === null) {
      if (scenario === 'stall') {
        input = pair(stalledAt !== null && time - stalledAt >= 5 ? 2 / 3 : 1);
        if (backflyAt !== null && time - backflyAt >= 5) handedAt = time;
      } else {
        input = pair(time % 7 < 1.5 ? 1 : 0);
        if (g.tuck > 0) { handedAt = time; input = pair(); }
      }
    }
    if (pending && tick >= pending.at) { input = pending.input; pending = null; }
    const frame = inputFrame(input);
    recorder.push(frame);
    frameInput(frame, controls);
    Object.assign(controls, summary.step(controls));
    stepFlight(g, controls, {}, dt); watch.step(dt, g, false, controls); style.step(dt, world);
    if (checkAt.has(recorder.steps)) checkpoints.push({ step: recorder.steps, snapshot: brakeSnapshot(world) });
    if (g.wingPhase !== lastPhase) { phases.push({ step: recorder.steps, phase: g.wingPhase }); lastPhase = g.wingPhase; }
    if (g.stall > 0 && stalledAt === null) stalledAt = time;
    if (g.wingPhase === WING.backfly && backflyAt === null) backflyAt = time;
    if (handedAt !== null) {
      const message = coach.step(dt, { g, watch: watch.state, input: controls, clearance: g.pos.y });
      if (message && !pending && message.action !== lastAction) {
        let amount;
        if (message.action === 'deep-brake') amount = 1;
        else if (message.action === 'brake') amount = 2 / 3;
        else if (['release-all', 'release-brake', 'straight'].includes(message.action)) amount = 0;
        if (amount !== undefined) pending = { at: tick + 10, input: pair(amount) };
        lastAction = message.action;
      }
      if (g.wingPhase === WING.flying && watch.state.calm >= 1) { recoveredAt = time; break; }
    }
  }
  if (recoveredAt === null || recoveredAt - handedAt! >= 30) throw new Error(`Direct ${scenario} did not recover`);
  const link = encodeLog({ simVersion: SIM_VERSION, glider: 'classic', seed: 0, total: style.state.total, peak: origin.y }, recorder.bits, recorder.steps);
  return { kind: scenario, pureFlight: true, simVersion: SIM_VERSION, origin, steps: recorder.steps, link,
    metrics: { handedAt, recoveredAt, heightLoss: origin.y - g.pos.y }, phases, checkpoints, snapshot: brakeSnapshot(world) };
}

/** Replay frozen browser input independently of the scripted capture pilot. */
export interface BrakeCaptureInput { pureFlight:boolean;origin?:Vector3;seed?:number;checkpoints: readonly {step:number}[] }
export function replayBrakeCapture(record: BrakeCaptureInput, frames: ArrayLike<number>) {
  const world = record.pureFlight ? { g: createFlight({ ...record.origin! }), watch: createSwingWatch(), style: createStyle(), controls: {} } :
    startRun(createRunWorld({ sky: createCloudbaseRun(), meet: createMeet(), bells: createBells(), style: createComboStyle(), wing: RUN_WING }), record.seed!);
  const summary = createControlSummary(), wanted = new Set(record.checkpoints.map(check => check.step)), checkpoints = [];
  let ending = null;
  for (let tick = 0; tick < frames.length; tick++) {
    if (record.pureFlight) {
      frameInput(frames[tick], world.controls);
      Object.assign(world.controls, summary.step(world.controls));
      stepFlight(world.g, world.controls, {}, dt);
      world.watch.step(dt, world.g, false, world.controls); world.style!.step(dt, world as RunWorld);
    } else ending = stepFrame(world as RunWorld, frames[tick]);
    if (wanted.has(tick + 1)) checkpoints.push({ step: tick + 1, snapshot: brakeSnapshot(world) });
  }
  if (!record.pureFlight) finishRun(world as RunWorld, ending ?? 'quit');
  return { checkpoints, snapshot: brakeSnapshot(world), ...(!record.pureFlight ? { sheet: summariseRun(world as RunWorld, ending ?? 'quit') } : {}) };
}
